VALUES ('casual', 1, 'What do you look to gain by joining Alpha Kappa Psi? And why?', NULL, true, 'score_notes', '[{"value":1.5,"label":"Exemplary","descriptors":["They mention growing professionally and pushing themselves for their future","Brings up giving back to the fraternity as well","Mentions wanting to be a part of the greater community","Seems genuine overall"]},{"value":1,"label":"Good","descriptors":["Provides good reasons for joining such as professional tips and individual growth","Generally good answer that talks about being part of the community","Wants to grow as an individual"]},{"value":0.5,"label":"Fair","descriptors":["Pretty basic response, typically saying professional development","No real mention of community or personal growth"]},{"value":0,"label":"Poor","descriptors":["Does not answer the question or inappropriate response"]}]'::jsonb, NULL, true, true, NULL);
VALUES ('casual', 2, 'What do you think your best character trait is and why?', NULL, true, 'score_notes', '[{"value":1.5,"label":"Exemplary","descriptors":["Provides a clear and thorough answer explaining what it means to them","Mentions having a community to rely on and give back to","Offers a unique perspective or addition to the table"]},{"value":1,"label":"Good","descriptors":["Provides a clear and interesting opinion","Mentions the idea of community and bonding"]},{"value":0.5,"label":"Fair","descriptors":["Attempts to offer a unique perspective but lacks detail and individuality","Does not provide a clear and compelling answer","Attempts to answer as best they can"]},{"value":0,"label":"Poor","descriptors":["Does not answer the question or inappropriate response"]}]'::jsonb, NULL, true, true, 'Source rubric text describes brotherhood and community, which does not match this prompt. Likely displaced from another question in the original document. Recruitment team must supply correct tier text.');
VALUES ('casual', 3, 'What is something you''re deeply passionate about?', NULL, true, 'score_notes', '[{"value":1.5,"label":"Exemplary","descriptors":["Shows passion for a subject and describes it well","Provides an interesting perspective","You can observe their care for the subject","They seem genuine and show creativity in their response"]},{"value":1,"label":"Good","descriptors":["Answers well and has an evident care for the subject","Explains an interesting perspective, but could be more interesting or detailed","You can see that they care"]},{"value":0.5,"label":"Fair","descriptors":["Shares a passion but seems to be dry in response","Provides good reasoning and some detail","Has at least some care of subject"]},{"value":0,"label":"Poor","descriptors":["Does not answer the question or inappropriate response"]}]'::jsonb, NULL, true, true, 'Tier text in the source PDF overflows across table boundaries. Fair and Good tiers are partially interleaved. Verify before the cycle opens.');
VALUES ('casual', 4, 'Creative question. Choose one and ask it to every PNM in this time slot: (1) It''s a late weeknight and you are super tired, but your friends invite you to hang out with them. You know you have another busy day tomorrow. What do you do? (2) You find yourself working with a brother who has a completely different personality from you. How do you approach building a connection? (3) If you could only read one book for the rest of your life, what would it be? (4) If you could have dinner with any person from history, dead or alive, who would you choose?', 'Coordinate with the other interviewers. All PNMs in the time slot must receive the same prompt.', true, 'score_notes', '[{"value":1.5,"label":"Exemplary","descriptors":["Answers the question with a creative and interesting response","Shows their personality in a fun and engaging way","Displays an innovative way of thinking"]},{"value":1,"label":"Good","descriptors":["Answers the question, but response lacks a unique way of thinking","Shows some personality, but not super engaging"]},{"value":0.5,"label":"Fair","descriptors":["Provides a response that is lacking in creativity","Is not engaging or showing personality"]},{"value":0,"label":"Poor","descriptors":["Does not answer the question or inappropriate response"]}]'::jsonb, NULL, true, true, NULL);
VALUES ('casual', 5, 'Do you have any questions that you would like to ask us?', NULL, true, 'score_notes', '[{"value":1.5,"label":"Exemplary","descriptors":["Asks at least one meaningful question about your own experience in AKPsi, opportunities provided, or any other meaningful content"]},{"value":1,"label":"Good","descriptors":["Only asks a question or questions about bid status or invite-only invitations"]},{"value":0,"label":"Poor","descriptors":["Does not ask any questions"]}]'::jsonb, NULL, true, true, NULL);
