VALUES ('professional', 1, 'Tell me about yourself.', NULL, true, 'score_notes', '[{"value":3,"label":"Exemplary","descriptors":["Provides basic characteristics such as major, year, name, hometown","Brings up BOTH personal values or goals and interest for joining AKPsi","Evident that the rushee cares and wants to join AKPsi, whether for professional or personal reasons, and that AKPsi will help them in their future endeavors","Clear interest, excitement, authentic, intentional, and personable"]},{"value":2,"label":"Good","descriptors":["Provides basic characteristics such as major, year, name, hometown","Brings up personal values or goals OR interest for joining AKPsi","Seems slightly or mildly interested in AKPsi","Shows interest, though motivation or alignment may be surface-level"]},{"value":1,"label":"Fair","descriptors":["Provides basic characteristics such as major, year, name, hometown","Does NOT bring up personal values or goals or interest for joining AKPsi","Vague and basic answer, no passion or drive for AKPsi","Response feels generic, rehearsed, or disengaged"]},{"value":0,"label":"Poor","descriptors":["Does not answer the question or inappropriate response"]}]'::jsonb, NULL, true, false, NULL);
VALUES ('professional', 2, 'What motivates you to rush Alpha Kappa Psi and what unique perspective would you bring to our brotherhood?', NULL, true, 'score_notes', '[{"value":3,"label":"Exemplary","descriptors":["Provides a clear and compelling reason for interest in joining","Mentions BOTH professional and community reasons for joining","Offers a unique perspective or addition to the table, such as aiming to seek leadership or give back to the fraternity"]},{"value":2,"label":"Good","descriptors":["Provides a clear and compelling reason for interest in joining","Mentions professional OR community reasons for joining","Attempts to offer a unique perspective but lacks detail and individuality"]},{"value":1,"label":"Fair","descriptors":["Does NOT provide a clear and compelling reason for interest, for example was told to apply or for a resume","Does not mention professional or community reasons for joining","Does NOT offer or attempt to offer a unique perspective"]},{"value":0,"label":"Poor","descriptors":["Does not answer the question or inappropriate response"]}]'::jsonb, NULL, true, false, NULL);
VALUES ('professional', 3, 'What role do you naturally take on in a team, and how do you adapt when the team needs something different from you?', NULL, true, 'score_notes', '[{"value":3,"label":"Exemplary","descriptors":["Clearly identifies their natural role on a team, whatever that may be","Demonstrates willingness to step outside that role when needed, indicating that they are adaptable and personable","Demonstrates a unique perspective or insight into conflict resolution, collaboration, or adaptability","Explains in depth their position on a team, passion for teamwork, and desire to grow","Reflects comfort supporting others and learning from teammates, or a desire to get better at teamwork"]},{"value":2,"label":"Good","descriptors":["Identifies a team role","Acknowledges adaptability, but explanation lacks depth","Attempts to show perspective or insight into conflict resolution, collaboration, or adaptability, but lacks detail or individuality","Attempts to show genuine passion for teamwork and a genuine willingness to grow and learn","Shows general understanding of teamwork"]},{"value":1,"label":"Fair","descriptors":["Provides a vague or generic example with minimal connection to teamwork or leadership","Limited reflection on adaptability or teamwork","Does not seem interested in teamwork or learning more about teamwork","Unclear understanding of how they contribute in group settings and does not show desire to learn more","Does not offer perspective or insight into conflict resolution, collaboration, or adaptability"]},{"value":0,"label":"Poor","descriptors":["Does not answer the question or inappropriate response"]}]'::jsonb, NULL, true, false, NULL);
VALUES ('professional', 4, 'What are each of your involvement and job commitments for this year? This includes other organizations and activities you are considering joining and getting involved in. How would you stay organized and manage your priorities when you have competing obligations while pledging?', NULL, true, 'score_notes', '[{"value":3,"label":"Exemplary","descriptors":["Details each involvement and what a typical week looks like","Explains current and anticipated commitments","Includes time management tools such as calendars and to-do lists, and a process for prioritizing by urgency and importance","Demonstrates realistic understanding of time and responsibility","Specifies prioritizing AKPsi and pledging"]},{"value":2,"label":"Good","descriptors":["Details each involvement and what a typical week looks like","Includes time management tools and a process for prioritizing","Mentions organization or prioritization strategies","Does NOT specify prioritizing AKPsi or pledging"]},{"value":1,"label":"Fair","descriptors":["Fails to detail each involvement and what a typical week looks like, or lacks detail regarding time management tools and process for prioritizing","Gives a vague or incomplete overview of commitments","Lacks a clear plan for managing responsibilities","Does NOT specify prioritizing AKPsi or pledging and raises concern about overcommitting or not being prepared for pledging"]},{"value":0,"label":"Poor","descriptors":["Does not answer the question or inappropriate response"]}]'::jsonb, NULL, true, false, NULL);
VALUES ('professional', 5, 'Where do you ideally see yourself in 5 years post-graduation, and how will Alpha Kappa Psi help you reach that goal?', NULL, true, 'score_notes', '[{"value":3,"label":"Exemplary","descriptors":["Clearly explains how AKPsi will support their development through mentorship, people, opportunities, and values","Articulates a thoughtful and realistic vision for their future, indicating they are motivated and passionate","Explicitly connects AKPsi opportunities such as committees, mentorship, workshops, networking, and professional trips to how they will grow","Focuses on personal and professional growth, not just outcomes or titles","Shows genuine motivation and a forward-thinking mindset"]},{"value":2,"label":"Good","descriptors":["Describes a general idea of where they see themselves in 5 years","Mentions growth or development, but vision is broad or loosely defined","Attempts to appear motivated and excited for their future","Makes some connection to AKPsi resources, but explanation is vague or surface-level"]},{"value":1,"label":"Fair","descriptors":["Vision is vague, unrealistic, or overly focused on job titles or status","Demonstrates a lack of understanding of the world","Provides little to no reasoning for why it matters or how AKPsi will specifically help","Limited evidence of intentionality or long-term thinking"]},{"value":0,"label":"Poor","descriptors":["Does not identify any professional growth area","Provides irrelevant, inappropriate, or unclear response","Fails to connect answer to AKPsi"]}]'::jsonb, NULL, true, false, NULL);
VALUES ('professional', 6, 'You have 1 minute to present a niche topic that you are passionate about.', 'Professional advisors may interrupt and push back. Run a timer. The rushee should be reaching roughly 50 seconds.', true, 'score_notes', '[{"value":3,"label":"Exemplary","descriptors":["Crafts a compelling story of their passion and maintains excitement","Shows genuine passion and takes on the challenge, while displaying authenticity and creativity","Performed well under pressure"]},{"value":2,"label":"Good","descriptors":["Crafts a compelling story of their passion and maintains excitement","Could show more passion or creativity","Attempted to perform well under pressure, seeming less engaging or expressive"]},{"value":1,"label":"Fair","descriptors":["Presents passion but does not seem engaged or excited","Could show more passion, authenticity, or creativity","Passion is limited or unclear","Appears uncomfortable or disengaged","Effort feels minimal or forced"]},{"value":0,"label":"Poor","descriptors":["Does not answer the question or inappropriate response"]}]'::jsonb, 60, true, false, NULL);
VALUES ('professional', 7, 'Do you have any questions for us?', 'Everyone may answer professional questions. For personal or casual questions, the professional advisor may not answer or acknowledge the question.', true, 'score_notes', '[{"value":2,"label":"Exemplary","descriptors":["Asks multiple questions","Asks deeper questions that show the rushee is curious about the pledging and business fraternity experience"]},{"value":1,"label":"Fair","descriptors":["Asks at least one question","Asks surface-level questions that do not demonstrate curiosity in the pledging and business fraternity experience"]},{"value":0,"label":"Poor","descriptors":["Does not ask any questions"]}]'::jsonb, NULL, true, false, NULL);


