INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'opening', 0, 'Introduce yourself, your role in AKPsi, as well as major and year.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'opening', 1, 'Explain that we will be taking notes, but it''s nothing to worry about.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'opening', 2, 'Have PNMs introduce themselves with their year and major as well.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'opening', 3, 'Questions will then be asked down the line by each interviewer.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'closing', 0, 'This concludes your casual interview.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'closing', 1, 'Due to the nature of the interview, please do not discuss interview questions or content with anyone outside of this room, including other potential new members.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'interviewer_notes', 0, 'Interviews must be kept to 15 minutes with 5 minutes of transition time.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'interviewer_notes', 1, 'Each brother is assigned one PNM to record answers for and score. One rubric per PNM.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'interviewer_notes', 2, 'If you know a PNM you cannot complete the rubric for them. Flag the conflict so a director can reassign you.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'interviewer_notes', 3, 'Do not discuss scores with your co-interviewers until after you have submitted.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'interviewer_notes', 4, 'Passion and genuine interest in growing is the main thing we want. An imperfect answer from a good fit can still earn a 1.5. Be honest and earnest.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('casual', 'interviewer_notes', 5, 'Question 4 is a choice of four creative prompts. Coordinate with the other interviewers so all PNMs in the time slot receive the same one.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('professional', 'opening', 0, 'Welcome to the Alpha Kappa Psi Professional Rush Interviews. We are excited to have you at this step of the process. Please remember to be yourself and be passionate.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('professional', 'opening', 1, 'Introduce yourselves. Traditionally, whoever asks the first question introduces themselves last.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('professional', 'opening', 2, 'Let''s get started with our questions.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('professional', 'closing', 0, 'Please make sure to keep {invite_event_dates} open in the event you are offered the opportunity to pledge. Additionally, you must be available every Monday and every Tuesday night, and occasionally Thursday nights.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('professional', 'closing', 1, 'Everything seen or heard during this interview is of a confidential nature and must not be shared with anyone who has not completed the pledging process. If we are made aware that what was said and asked here leaves the room, you will be removed from any further consideration. Do you understand?');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('professional', 'interviewer_notes', 0, 'Designate one person, typically the person who is not E-Board or a professional advisor, to focus on taking notes while the rushee speaks. All panelists are still expected to take notes during the interview and score afterward.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('professional', 'interviewer_notes', 1, 'If you do not complete your rubric in its entirety it is null and void. Every question requires a score before you can submit.');
INSERT INTO interview_scripts (type, kind, position, content) VALUES ('professional', 'conflict_script', 0, 'Shown only when the panelist has flagged knows_personally: "Regardless of any experiences you have had in the past with me or anyone else on the professional team, our relationship when it comes to Alpha Kappa Psi will remain professional, strictly professional, and nothing but professional. Is this understood?"');
